import { useEffect, useRef, useState } from "react";

export default function AdminGallery() {
  const [images, setImages] = useState([]);
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState("");
  const [error, setError] = useState("");

  const fileRef = useRef(null);

  // ================= LOAD IMAGES (ALWAYS FROM DB) =================
  const fetchImages = async () => {
    try {
      const token = localStorage.getItem("adminToken");

      if (!token) {
        console.error("❌ No admin token found");
        return;
      }

      const res = await fetch("http://localhost:5001/admin/gallery", {
        headers: {
          Authorization: "Bearer " + token,
        },
      });

      if (!res.ok) {
        throw new Error("Failed to fetch images");
      }

      const data = await res.json();

      // 🔥 SAFETY CHECK
      if (Array.isArray(data)) {
        setImages(data);
      } else {
        setImages([]);
      }
    } catch (err) {
      console.error("❌ Gallery load error:", err);
      setError("Failed to load images");
    }
  };

  // LOAD ON PAGE OPEN / REFRESH
  useEffect(() => {
    fetchImages();
  }, []);

  // ================= FILE SELECT =================
  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setPreview(URL.createObjectURL(file));
    setSuccess("");
    setError("");
  };

  // ================= UPLOAD IMAGE =================
  const handleUpload = async () => {
    const file = fileRef.current?.files[0];
    if (!file) return;

    setLoading(true);
    setSuccess("");
    setError("");

    const token = localStorage.getItem("adminToken");
    if (!token) {
      setError("Not authenticated");
      setLoading(false);
      return;
    }

    const formData = new FormData();
    formData.append("image", file);

    try {
      const res = await fetch("http://localhost:5001/admin/gallery", {
        method: "POST",
        headers: {
          Authorization: "Bearer " + token,
        },
        body: formData,
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data?.error || "Upload failed");
      }

      // ✅ INSTANT UI UPDATE
      setImages((prev) => [
        {
          id: data.id,
          image_url: data.image_url,
        },
        ...prev,
      ]);

      setSuccess("✅ Image uploaded successfully");

      // RESET INPUT + PREVIEW
      fileRef.current.value = "";
      setPreview(null);
    } catch (err) {
      console.error("❌ Upload error:", err);
      setError("Image upload failed");
    } finally {
      setLoading(false);
    }
  };

  // ================= UI =================
  return (
    <div className="p-10 text-white">
      {/* Title */}
      <h1 className="text-3xl font-bold text-yellow-400 mb-8">
        Gallery Manager
      </h1>

      {/* Upload Card */}
      <div className="bg-[#0d0d0d] border border-yellow-500/40 rounded-2xl p-6 max-w-xl shadow-lg">
        <p className="text-gray-400 mb-3 text-sm">
          Upload high quality fitness images
        </p>

        <input
          ref={fileRef}
          type="file"
          accept="image/*"
          onChange={handleFileChange}
          className="block w-full text-sm text-gray-300
          file:bg-yellow-400 file:text-black file:border-0
          file:px-5 file:py-2 file:rounded-xl
          file:font-semibold cursor-pointer"
        />

        {/* Preview */}
        {preview && (
          <div className="mt-6">
            <p className="text-sm text-gray-400 mb-2">Preview</p>
            <img
              src={preview}
              alt="preview"
              className="w-44 h-44 object-cover rounded-xl border border-yellow-500/50"
            />
          </div>
        )}

        {/* Upload Button */}
        <button
          onClick={handleUpload}
          disabled={loading}
          className="mt-6 bg-yellow-400 text-black px-8 py-2 rounded-xl font-semibold
          hover:bg-yellow-500 transition disabled:opacity-60"
        >
          {loading ? "Uploading..." : "Upload Image"}
        </button>

        {/* Messages */}
        {success && (
          <div className="mt-4 text-green-400 font-medium animate-pulse">
            {success}
          </div>
        )}

        {error && (
          <div className="mt-4 text-red-400 font-medium">
            {error}
          </div>
        )}
      </div>

      {/* Gallery */}
      <h2 className="text-xl font-semibold mt-12 mb-6 text-yellow-400">
        Uploaded Images
      </h2>

      {images.length === 0 ? (
        <p className="text-gray-500">No images uploaded yet</p>
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
          {images.map((img) => (
            <div
              key={img.id}
              className="group relative border border-yellow-500/30 rounded-xl overflow-hidden"
            >
              <img
                src={`http://localhost:5001${img.image_url}`}
                alt="gallery"
                className="w-full h-44 object-cover group-hover:scale-110 transition duration-300"
              />
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
